fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let gx: i32 = 60;
    let gy: i32 = 60;
    let cs: i32 = 20;
    if down == 1 {
        let cx: i32 = (px - gx) / cs;
        let cy: i32 = (py - gy) / cs;
        if px >= gx && py >= gy && cx < 16 && cy < 16 {
            let row: i32 = host::display::state_get(10 + cy);
            host::display::state_set(10 + cy, row | (1 << cx));
        }
    }
    if down == 1 && prev == 0 && px >= 60 && px < 140 && py >= 20 && py < 48 {
        let mut r: i32 = 0;
        while r < 16 {
            host::display::state_set(10 + r, 0);
            r = r + 1;
        }
    }
    host::display::state_set(0, down);
    host::display::clear(0x101010);
    host::display::fill_rect(60, 20, 80, 28, 0x802020);
    host::display::draw_string(72, 30, "CLEAR", 0xffffff, 1);
    host::display::fill_rect(gx - 2, gy - 2, cs * 16 + 4, cs * 16 + 4, 0x303030);
    host::display::fill_rect(gx, gy, cs * 16, cs * 16, 0x000000);
    let mut y: i32 = 0;
    while y < 16 {
        let row: i32 = host::display::state_get(10 + y);
        let mut x: i32 = 0;
        while x < 16 {
            if ((row >> x) & 1) == 1 {
                host::display::fill_rect(gx + x * cs, gy + y * cs, cs, cs, 0xffffff);
            }
            x = x + 1;
        }
        y = y + 1;
    }
    host::display::present();
}
